      .replace(/[^\w]+/g, '_')                         // espacios y símbolos -> _
      .replace(/^_+|_+$/g, '')                         // recorta _
      .replace(/_+/g, '_')                             // colapsa __
      .toUpperCase();

  const toNumber = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };

  const groups = new Map();

  for (const r of rows) {
    const semana = r.Semana;
    const sucursal = r.Sucursal;
    const key = `${semana}||${sucursal}`;

    if (!groups.has(key)) {
      groups.set(key, {
        Semana: semana,
        Sucursal: sucursal,
        sum_Abono_Libre: toNumber(r.sum_Abono_Libre ?? 0),
      });
