    const g = groups.get(key);

    const catKey = `sum_${normalizeKey(r.Categoria)}`;
    g[catKey] = (g[catKey] ?? 0) + toNumber(r.sum_Pagado_Prestación ?? 0);
  }

  return Array.from(groups.values()).map(obj => ({ json: obj }));
}

