const TZ = 'America/Montevideo';
const pad = n => String(n).padStart(2, '0');

// Fecha inicio fija
const inicio = new Date(Date.UTC(2026, 2, 10)); // 10 mar, medianoche UTC

// Hoy en Montevideo con en-CA → formato YYYY-MM-DD confiable
const hoyStrMVD = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
const [y, m, d] = hoyStrMVD.split('-').map(Number);
const ayer = new Date(Date.UTC(y, m - 1, d - 1)); // ayer, medianoche UTC

const items = [];
const cursor = new Date(inicio);

while (cursor <= ayer) {
  const diaSemana = cursor.getUTCDay(); // 0 = domingo

  if (diaSemana !== 0) {
    const yyyy = cursor.getUTCFullYear();
    const mm = pad(cursor.getUTCMonth() + 1);
    const dd = pad(cursor.getUTCDate());
    const fecha = `${yyyy}-${mm}-${dd}`;

    const url = "https://api.dentalink.healthatom.com/api/v1/pagos?q="
      + encodeURIComponent('{"fecha_recepcion":{"eq":"' + fecha + '"}}');

    // Usar mediodía UTC para el display evita cualquier ambigüedad de timezone
    const fechaDisplayRaw = new Date(fecha + 'T12:00:00Z').toLocaleDateString('es-UY', {
      timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long'
    });
    const fechaDisplay = fechaDisplayRaw.charAt(0).toUpperCase() + fechaDisplayRaw.slice(1);

    items.push({ json: { fecha, url, fechaDisplay } });
  }

  cursor.setUTCDate(cursor.getUTCDate() + 1);
}

return items;

const allItems = $input.all().map(i => i.json);

const fmt = n => '$' + Number(n || 0).toLocaleString('es-UY', { minimumFractionDigits: 0 });

const ORDEN_SUCS = ['suy 1', 'suy 2', 'suy 3', 'suy 4'];
const sortSuc = (a, b) => {
  const ia = ORDEN_SUCS.findIndex(s => a.toLowerCase().includes(s));
  const ib = ORDEN_SUCS.findIndex(s => b.toLowerCase().includes(s));
  return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
};

const CATEGORIAS = [
  { key: 'sum_ORTODONCIA',            label: 'ORTODONCIA' },
  { key: 'sum_GENERAL',               label: 'GENERAL' },
  { key: 'sum_PROTESIS',              label: 'PRÓTESIS' },
  { key: 'sum_ENDODONCIA',            label: 'ENDODONCIA' },
  { key: 'sum_CIRUGIA',               label: 'CIRUGÍA' },
  { key: 'sum_ORTOPEDIA',             label: 'ORTOPEDIA' },
  { key: 'sum_PERIODONCIA',           label: 'PERIODONCIA' },
  { key: 'sum_RADIOLOGIA',            label: 'RADIOLOGÍA' },
  { key: 'sum_PRODUCTOS_HIGIENE_BUCAL', label: 'HIGIENE BUCAL' },
  { key: 'sum_ALINEADORES',           label: 'ALINEADORES' },
];

const SUBCATS = [
  { key: 'pagadoAJUSTE', label: 'Ajustes' },
  { key: 'pagadoRETIRO', label: 'Retiros' },
  { key: 'pagadoCOMBO',  label: 'Combos' },
];

// Agrupar y sumar por sucursal (por si hay múltiples semanas)
const porSucursal = {};
for (const item of allItems) {
  const suc = item.Sucursal;
  if (!porSucursal[suc]) {
    porSucursal[suc] = {};
    [...CATEGORIAS, ...SUBCATS].forEach(c => porSucursal[suc][c.key] = 0);
  }
  [...CATEGORIAS, ...SUBCATS].forEach(c => {
    porSucursal[suc][c.key] += item[c.key] || 0;
  });
}

const sucursales = Object.keys(porSucursal).sort(sortSuc);

// Secciones por sucursal
const secciones = sucursales.map(suc => {
  const d = porSucursal[suc];

  const filas = CATEGORIAS
    .filter(c => d[c.key] > 0)
    .sort((a, b) => d[b.key] - d[a.key])
    .map((c, _, arr) => {
      const isOrtodoncia = c.key === 'sum_ORTODONCIA';

      const subcatRows = isOrtodoncia
        ? SUBCATS
            .filter(s => d[s.key] > 0)
            .map((s, idx) => `
              <tr>
                <td style="padding:3px 0 3px 18px;color:#999;font-size:12px;">${idx + 1}. ${s.label}</td>
                <td style="padding:3px 0;text-align:right;color:#999;font-size:12px;">${fmt(d[s.key])}</td>
              </tr>`)
            .join('')
        : '';

      return `
        <tr>
          <td style="padding:5px 0 ${isOrtodoncia ? '2px' : '5px'} 0;color:#555;font-size:14px;">${c.label}</td>
          <td style="padding:5px 0;text-align:right;color:#333;font-size:14px;">${fmt(d[c.key])}</td>
        </tr>
        ${subcatRows}`;
    }).join('');

  const totalSuc = CATEGORIAS.reduce((acc, c) => acc + d[c.key], 0);

  return `
    <div style="margin-bottom:28px;">
      <div style="font-size:13px;font-weight:600;color:#888;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;">${suc}</div>
      <table style="width:100%;border-collapse:collapse;">
        ${filas}
        <tr style="border-top:1px solid #e0e0e0;">
          <td style="padding:7px 0;font-weight:700;color:#111;font-size:14px;">Total</td>
          <td style="padding:7px 0;text-align:right;font-weight:700;color:#111;font-size:15px;">${fmt(totalSuc)}</td>
        </tr>
      </table>
    </div>`;
}).join('');

const totalGeneral = sucursales.reduce((acc, suc) =>
  acc + CATEGORIAS.reduce((a, c) => a + porSucursal[suc][c.key], 0), 0);

const tz='America/Montevideo';
const now=DateTime.now().setZone(tz).startOf('day');
const jsDow=now.toJSDate().getDay();
const sat=now.minus({days:(jsDow+1)%7});
const f=(d)=>d.plus({days:(6-d.weekday+7)%7});
const curr=sat.startOf('month');const prevEnd=curr.minus({days:1});const prev=prevEnd.startOf('month');
const meso=sat.hasSame(f(prevEnd),'day')?prev:curr;
const M=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const mesLabel = M[meso.month-1] + ' ' + meso.year;

const html = `
<div style="font-family:sans-serif;max-width:520px;color:#333;">
  <p style="font-size:13px;color:#999;margin:0 0 4px;">Reporte Mensual por categoría</p>
  <h2 style="font-size:20px;margin:0 0 24px;color:#111;">${mesLabel}</h2>

  ${secciones}

  <div style="background:#f4f4f4;border-radius:6px;padding:12px 16px;">
    <table style="width:100%;border-collapse:collapse;">
      <tr>
        <td style="font-weight:700;color:#111;font-size:14px;">Total general</td>
        <td style="text-align:right;font-weight:700;font-size:16px;color:#111;">${fmt(totalGeneral)}</td>
      </tr>
    </table>
  </div>
</div>`;

return [{ json: { html, totalGeneral, mesLabel } }];
